import { getAuthHeaders } from "./auth";

// API Configuration
const API_BASE_URL = process.env.NEXT_PUBLIC_API_URL;

// Types

/**
 * Build full API URL
 */
function buildUrl(endpoint) {
  const cleanEndpoint = endpoint.startsWith("/") ? endpoint : `/${endpoint}`;
  return `${API_BASE_URL}${cleanEndpoint}`;
}

/**
 * Handle API response
 */
async function handleResponse(response) {
  // Handle errors (401, 403, 500, etc.)
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));

    // Return error details without forcing a logout to prevent unintended data loss in editors
    return {
      success: false,
      status: response.status,
      code: errorData.code,
      data: errorData.data,
      error:
        errorData.message || `Request failed with status ${response.status}`,
    };
  }

  // Parse successful response
  try {
    const data = await response.json();
    return { success: true, data };
  } catch {
    return { success: true };
  }
}

/**
 * Generic GET request
 */
export async function apiGet(endpoint) {
  try {
    const response = await fetch(buildUrl(endpoint), {
      method: "GET",
      headers: {
        ...getAuthHeaders(),
        "Content-Type": "application/json",
        "ngrok-skip-browser-warning": "true",
      },
      credentials: "include", // Ensure cookies are sent
    });
    return handleResponse(response);
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : "Network error",
    };
  }
}

/**
 * Generic POST request
 */
export async function apiPost(endpoint, body) {
  try {
    const response = await fetch(buildUrl(endpoint), {
      method: "POST",
      headers: {
        ...getAuthHeaders(),
        "Content-Type": "application/json",
        "ngrok-skip-browser-warning": "true",
      },
      body: body ? JSON.stringify(body) : undefined,
      credentials: "include",
    });
    return handleResponse(response);
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : "Network error",
    };
  }
}

/**
 * Generic PUT request
 */
export async function apiPut(endpoint, body) {
  try {
    const response = await fetch(buildUrl(endpoint), {
      method: "PUT",
      headers: {
        ...getAuthHeaders(),
        "Content-Type": "application/json",
        "ngrok-skip-browser-warning": "true",
      },
      body: body ? JSON.stringify(body) : undefined,
      credentials: "include",
    });
    return handleResponse(response);
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : "Network error",
    };
  }
}

/**
 * Generic PATCH request
 */
export async function apiPatch(endpoint, body) {
  try {
    const response = await fetch(buildUrl(endpoint), {
      method: "PATCH",
      headers: {
        ...getAuthHeaders(),
        "Content-Type": "application/json",
        "ngrok-skip-browser-warning": "true",
      },
      body: body ? JSON.stringify(body) : undefined,
      credentials: "include",
    });
    return handleResponse(response);
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : "Network error",
    };
  }
}

/**
 * Generic DELETE request
 */
export async function apiDelete(endpoint, body) {
  try {
    const response = await fetch(buildUrl(endpoint), {
      method: "DELETE",
      headers: {
        ...getAuthHeaders(),
        ...(body ? { "Content-Type": "application/json" } : {}),
        "ngrok-skip-browser-warning": "true",
      },
      body: body ? JSON.stringify(body) : undefined,
      credentials: "include",
    });
    return handleResponse(response);
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : "Network error",
    };
  }
}

export async function apiPostFormData(endpoint, formData) {
  try {
    const headers = {
      ...getAuthHeaders(),
      "ngrok-skip-browser-warning": "true",
    };
    delete headers["Content-Type"];
    const response = await fetch(buildUrl(endpoint), {
      method: "POST",
      headers,
      body: formData,
      credentials: "include",
    });
    return handleResponse(response);
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : "Network error",
    };
  }
}

