export const assetsApi = {
  list: (params = {}) => apiGet(`/assets?${new URLSearchParams(params)}`),
  uploaders: () => apiGet("/assets/uploaders"),
  get: (id) => apiGet(`/assets/${id}`),
  usages: (id) => apiGet(`/assets/${id}/usages`),
  folders: (params = {}) => apiGet(`/assets/folders?${new URLSearchParams(params)}`),
  folder: (id) => apiGet(`/assets/folders/${id}`),
  createFolder: (data) => apiPost("/assets/folders", data),
  updateFolder: (id, data) => apiPatch(`/assets/folders/${id}`, data),
  trashFolder: (id) => apiPost(`/assets/folders/${id}/trash`),
  restoreFolder: (id) => apiPost(`/assets/folders/${id}/restore`),
  deleteFolderPermanently: (id) => apiDelete(`/assets/folders/${id}/permanent`),
  update: (id, data) => apiPatch(`/assets/${id}`, data),
  trash: (id) => apiPost(`/assets/${id}/trash`),
  restore: (id) => apiPost(`/assets/${id}/restore`),
  deletePermanently: (id) => apiDelete(`/assets/${id}/permanent`),
  bulk: async (action, ids, extra = {}) => {
    const response = await apiPost("/assets/bulk", { action, ids, ...extra });
    if (response.success && response.data?.success === false) {
      return {
        success: false,
        error: response.data.message || "One or more files could not be updated.",
        data: response.data.data,
      };
    }
    return response;
  },
  transfer: (operation, items, destinationFolderId = null) =>
    apiPost("/assets/transfer", { operation, items, destinationFolderId }),
  upload: (file, options = {}, onProgress) =>
    new Promise((resolve) => {
      const request = new XMLHttpRequest();
      request.open("POST", buildUrl("/assets/upload"));
      const token = getAuthHeaders().Authorization;
      if (token) request.setRequestHeader("Authorization", token);
      request.setRequestHeader("ngrok-skip-browser-warning", "true");
      request.withCredentials = true;
      request.upload.onprogress = (event) => {
        if (event.lengthComputable) onProgress?.(Math.round((event.loaded / event.total) * 100));
      };
      request.onload = () => {
        try {
          const payload = JSON.parse(request.responseText);
          resolve({
            success: request.status >= 200 && request.status < 300 && payload.success !== false,
            status: request.status,
            data: payload.data,
            error: payload.message,
          });
        } catch {
          resolve({ success: false, status: request.status, error: "Upload failed." });
        }
      };
      request.onerror = () => resolve({ success: false, error: "Upload failed." });
      const form = new FormData();
      form.append("files", file);
      if (options.folderId) form.append("folderId", options.folderId);
      form.append("visibility", options.visibility || "public");
      if (options.duplicateStrategy) form.append("duplicateStrategy", options.duplicateStrategy);
      request.send(form);
    }),
};

export const messagingApi = {
  conversations: (params = {}) =>
    apiGet(`/messaging/conversations?${new URLSearchParams(params)}`),
  team: (params = {}) =>
    apiGet(`/messaging/team?${new URLSearchParams(params)}`),
  startDirect: (userId) => apiPost("/messaging/direct", { userId }),
  messages: (conversationId, params = {}) =>
    apiGet(
      `/messaging/conversations/${conversationId}/messages?${new URLSearchParams(params)}`,
    ),
  send: (conversationId, content, clientId, options = {}) =>
    apiPost(`/messaging/conversations/${conversationId}/messages`, {
      content,
      clientId,
      ...options,
    }),
  markRead: (conversationId) =>
    apiPatch(`/messaging/conversations/${conversationId}/read`),
  unread: () => apiGet("/messaging/unread"),
  discussion: (entityType, entityId) =>
    apiPost("/messaging/discussions", { entityType, entityId }),
  members: (conversationId, search = "") =>
    apiGet(
      `/messaging/conversations/${conversationId}/members?${new URLSearchParams(search ? { search } : {})}`,
    ),
  edit: (messageId, content) =>
    apiPatch(`/messaging/messages/${messageId}`, { content }),
  delete: (messageId) => apiDelete(`/messaging/messages/${messageId}`),
  react: (messageId, emoji) =>
    apiPost(`/messaging/messages/${messageId}/reaction`, { emoji }),
  pin: (messageId) => apiPost(`/messaging/messages/${messageId}/pin`),
  pins: (conversationId) =>
    apiGet(`/messaging/conversations/${conversationId}/pins`),
  search: (params) =>
    apiGet(`/messaging/search?${new URLSearchParams(params)}`),
  context: (messageId) => apiGet(`/messaging/messages/${messageId}/context`),
  upload: (conversationId, files, onProgress) =>
    new Promise((resolve) => {
      const fileList = Array.isArray(files) ? files : Array.from(files || []);
      const request = new XMLHttpRequest();
      request.open(
        "POST",
        buildUrl(`/messaging/conversations/${conversationId}/attachments`),
      );
      const token = getAuthHeaders().Authorization;
      if (token) request.setRequestHeader("Authorization", token);
      request.setRequestHeader("ngrok-skip-browser-warning", "true");
      request.withCredentials = true;
      request.upload.onprogress = (event) =>
        event.lengthComputable &&
        onProgress?.(Math.round((event.loaded / event.total) * 100));
      request.onload = () => {
        try {
          const data = JSON.parse(request.responseText);
          resolve(
            request.status >= 200 && request.status < 300
              ? { success: true, data }
              : { success: false, error: data.message || "Upload failed" },
          );
        } catch {
          resolve({ success: false, error: "Upload failed" });
        }
      };
      request.onerror = () =>
        resolve({ success: false, error: "Upload failed" });
      const form = new FormData();
      fileList.forEach((file) => form.append("files", file));
      request.send(form);
    }),
  attachmentBlob: async (attachmentId) => {
    const response = await fetch(
      buildUrl(`/messaging/attachments/${attachmentId}`),
      {
        headers: { ...getAuthHeaders(), "ngrok-skip-browser-warning": "true" },
        credentials: "include",
      },
    );
    if (!response.ok) throw new Error("Attachment unavailable");
    return response.blob();
  },
};

/** Social Post Studio */
export const socialPostsApi = {
  list: (params = {}) => apiGet(`/social-posts?${new URLSearchParams(params)}`),
  get: (id) => apiGet(`/social-posts/${id}`),
  create: (data) => apiPost("/social-posts", data),
  update: (id, data) => apiPatch(`/social-posts/${id}`, data),
  duplicate: (id) => apiPost(`/social-posts/${id}/duplicate`),
  schedule: (id, data) => apiPost(`/social-posts/${id}/schedule`, data),
  cancelPublication: (id, pubId) =>
    apiPost(`/social-posts/${id}/publications/${pubId}/cancel`),
  uploadPublishingAssets: (id, files) => {
    const form = new FormData();
    Array.from(files || []).forEach((file) => form.append("files", file));
    return apiPostFormData(`/social-posts/${id}/publishing-assets`, form);
  },
  publish: (id, data) => apiPost(`/social-posts/${id}/publish`, data),
  publications: (id) => apiGet(`/social-posts/${id}/publications`),
  delete: (id) => apiDelete(`/social-posts/${id}`),
};

